import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Fused kernel to perform:
// GEMM -> Swish -> divide by 2 -> clamp(-1, 1) -> tanh -> clamp(-1, 1)
__global__ void fused_gemm_swish_div_clamp_tanh_clamp_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int batch_size, int in_features, int out_features
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_features;

    if (index < total) {
        int row = index / out_features;
        int col = index % out_features;

        float val = 0.0f;
        // GEMM
        for (int k = 0; k < in_features; k++) {
            val += x[row * in_features + k] * weight[col * in_features + k];
        }
        // Add bias
        val += bias[col];

        // Swish activation: x * sigmoid(x)
        float sig = 1.0f / (1.0f + expf(-val));
        val = val * sig;

        // Divide by 2
        val = val * 0.5f;

        // Clamp(-1, 1)
        val = fminf(fmaxf(val, -1.0f), 1.0f);

        // Tanh
        val = tanhf(val);

        // Clamp(-1, 1)
        val = fminf(fmaxf(val, -1.0f), 1.0f);

        out[row * out_features + col] = val;
    }
}

torch::Tensor fused_gemm_swish_div_clamp_tanh_clamp(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
) {
    // x: (batch_size, in_features)
    // weight: (out_features, in_features)
    // bias: (out_features)
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    int block_size = 256;
    int grid_size = (batch_size * out_features + block_size - 1) / block_size;

    fused_gemm_swish_div_clamp_tanh_clamp_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size, in_features, out_features
    );

    return out;
}
""";

fused_header = r"""
torch::Tensor fused_gemm_swish_div_clamp_tanh_clamp(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
);
""";

fused_module = load_inline(
    name="fused_module",
    cpp_sources=fused_header,
    cuda_sources=fused_source,
    functions=["fused_gemm_swish_div_clamp_tanh_clamp"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Fused model that performs GEMM, Swish, /2, clamp, tanh, clamp in a single CUDA kernel.
    """
    def __init__(self, in_features, out_features, bias=True):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        if bias:
            self.bias = nn.Parameter(torch.randn(out_features))
        else:
            self.register_parameter('bias', None)

    def forward(self, x):
        if self.bias is None:
            b = x.new_zeros((self.weight.size(0),))
        else:
            b = self.bias
        return fused_module.fused_gemm_swish_div_clamp_tanh_clamp(x, self.weight, b)
